bool Test(int first, int second) { Print("test" + first); return first < second; }
void Main() {
    var i = 0;
    do {
        i = i + 1;
        if (i == 1) continue;
        Print("body" + i);
    } while (Test(second: 2, first: i));
    do { Print("once"); } while (false);
    do { Print("break"); break; } while (Test(second: 9, first: i));
    do ; while (false);
    Print(i);
}
